#include <iostream>
using std::cout;
using std::endl;

enum ITEM_CATEGORY
{
    WEAPON,
    ARMOR,
    CONSUME
};

struct Item
{
    char szName[32];
    unsigned int iValue;
    ITEM_CATEGORY eCategory;
};

int main()
{
    Item tArr[3] = {
        { "강철검", 100, WEAPON },
        { "가죽갑옷", 80, ARMOR },
        { "빨간포션", 50, CONSUME }
    };

    for (int i = 0; i < 3; i++)
    {
        cout << i + 1 << "번 아이템: " << tArr[i].szName << " [";

        switch (tArr[i].eCategory)
        {
        case WEAPON:
            cout << "무기";
            break;
        case ARMOR:
            cout << "방어구";
            break;
        case CONSUME:
            cout << "소비";
            break;
        }

        cout << "] " << tArr[i].iValue << endl;
    }

    return 0;
}

