#include <iostream>
using std::cout;
using std::endl;

struct Item
{
    char szName[32];
    unsigned int iValue;
};

struct Inventory
{
    int iGold;
    unsigned char ucItemCount;
    Item tItemArr[10];
};

struct Player
{
    char szName[32];
    int iHP;
    Inventory tInventory;
};

int main()
{
    Player tP;

    strcpy_s(tP.szName, "찬연");
    tP.iHP = 100;
    tP.tInventory.iGold = 1000;
    tP.tInventory.ucItemCount = 0;

    strcpy_s(tP.tInventory.tItemArr[tP.tInventory.ucItemCount].szName, "강철검");
    tP.tInventory.tItemArr[tP.tInventory.ucItemCount].iValue = 100;
    tP.tInventory.ucItemCount++;

    strcpy_s(tP.tInventory.tItemArr[tP.tInventory.ucItemCount].szName, "빨간포션");
    tP.tInventory.tItemArr[tP.tInventory.ucItemCount].iValue = 50;
    tP.tInventory.ucItemCount++;

    cout << "이름: " << tP.szName << endl;
    cout << "HP: " << tP.iHP << endl;
    cout << "소지금: " << tP.tInventory.iGold << " Gold" << endl;
    cout << "인벤토리:" << endl;

    for (int i = 0; i < tP.tInventory.ucItemCount; i++)
    {
        cout << i + 1 << "번 아이템: " << tP.tInventory.tItemArr[i].szName
             << " (" << tP.tInventory.tItemArr[i].iValue << ")" << endl;
    }

    return 0;
}
